// Solo atiende al chat de TU_NOMBRE. /nuevo borra la memoria de la conversación.
const m = $json.body?.message;
const chat = String(m?.chat?.id || '');
const texto = String(m?.text || '').trim();
if (chat !== 'TU_CHAT_ID' || !texto) return [];
const memoria = $getWorkflowStaticData('global');
memoria.chats ||= {};
if (/^\/(nuevo|olvidar|reset)\b/i.test(texto)) {
  memoria.chats[chat] = [];
  return [{ json: { chat, texto, comando: 'nuevo' } }];
}
return [{ json: { chat, texto, comando: '', historial: (memoria.chats[chat] || []).slice(-12) } }];

// Arma una foto compacta de todo lo que hay en n8n para que la IA responda con datos reales.
const zona = 'America/Havana';
const ahora = $now.setZone(zona);
const corta = (s, n) => { s = String(s ?? '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const fecha = d => d ? DateTime.fromISO(String(d)).setZone(zona).toFormat('dd/MM HH:mm') : '—';

const flujos = $('Flujos').first().json.data || [];
const nombres = Object.fromEntries(flujos.map(w => [w.id, w.name]));
const disparador = n => {
  const p = n.parameters || {};
  if (n.type.endsWith('scheduleTrigger')) {
    const r = p.rule?.interval?.[0] || {};
    if (r.field === 'minutes') return `cada ${r.minutesInterval || 1} min`;
    if (r.field === 'weeks') return `semanal (día ${r.triggerAtDay}) a las ${r.triggerAtHour ?? 0}:00`;
    return `diario a las ${r.triggerAtHour ?? 0}:00`;
  }
  if (n.type.endsWith('emailReadImap')) return 'cada correo nuevo (IMAP)';
  if (n.type.endsWith('errorTrigger')) return 'cuando falla otro flujo';
  if (n.type.endsWith('webhook')) return `webhook /${p.path}`;
  return n.type.split('.').pop();
};
const bloques = flujos.map(w => {
  const trig = (w.nodes || []).find(n => /trigger|webhook|emailReadImap/i.test(n.type) && n.name !== 'Prueba');
  const orden = [];
  const vistos = new Set();
  const cola = trig ? [trig.name] : [];
  while (cola.length) {
    const n = cola.shift(); if (vistos.has(n)) continue; vistos.add(n); orden.push(n);
    for (const salida of (w.connections?.[n]?.main || [])) for (const c of (salida || [])) cola.push(c.node);
  }
  const notas = (w.nodes || []).filter(n => n.type.endsWith('.code')).map(n => {
    const lineas = String(n.parameters?.jsCode || '').split('\n').filter(l => l.trim().startsWith('//')).slice(0, 2).map(l => l.replace(/^\s*\/\/\s?/, ''));
    return lineas.length ? `${n.name}: ${lineas.join(' ')}` : '';
  }).filter(Boolean);
  const ia = (w.nodes || []).some(n => n.type.includes('langchain'));
  return `### ${w.name} (id ${w.id}) — ${w.active ? 'ACTIVO' : 'apagado'}\nSe dispara: ${trig ? disparador(trig) : 'manual'}${ia ? ' · usa IA (OpenRouter)' : ''}${w.settings?.errorWorkflow ? ' · si falla lo gestiona el Vigilante de errores' : ''}\nPasos: ${orden.join(' → ')}\n${notas.map(x => '- ' + corta(x, 220)).join('\n')}`;
});

const ejec = $('Ejecuciones').first().json.data || [];
const hace7 = ahora.minus({ days: 7 });
const est = {};
for (const e of ejec) {
  const f = est[e.workflowId] ||= { ok: 0, error: 0, ultima: null, estadoUltima: '' };
  if (DateTime.fromISO(e.startedAt) >= hace7) { if (e.status === 'success') f.ok++; else if (['error', 'crashed'].includes(e.status)) f.error++; }
  if (!f.ultima || e.startedAt > f.ultima) { f.ultima = e.startedAt; f.estadoUltima = e.status; }
}
const lineasEjec = Object.entries(est).map(([id, f]) => `- ${nombres[id] || id}: última ${fecha(f.ultima)} (${f.estadoUltima}); 7 días: ${f.ok} ok, ${f.error} con error`);
const errores = ($('Errores').first().json.data || []).map(e => {
  const rd = e.data?.resultData || {};
  return `- ${fecha(e.startedAt)} · ${nombres[e.workflowId] || e.workflowId} · nodo "${rd.lastNodeExecuted || '?'}" · ${corta(rd.error?.message, 160)}`;
});

const tablas = $('Tablas').first().json.data || [];
const filas = $('Filas').all();
const bloquesTablas = tablas.map((t, i) => {
  const rows = filas[i]?.json.data || [];
  const cols = t.columns.map(c => c.name);
  return `### Tabla "${t.name}" (${rows.length} filas; columnas: ${cols.join(', ')})\n` +
    rows.slice(0, 80).map(r => '- ' + cols.map(c => r[c] === null || r[c] === '' || r[c] === undefined ? '' : `${c}=${corta(r[c], 180)}`).filter(Boolean).join('; ')).join('\n');
});

const contexto = [
  `Fecha y hora actual: ${ahora.toFormat("cccc dd/MM/yyyy HH:mm", { locale: 'es' })} (tu ciudad).`,
  `## Flujos (${flujos.length})`, ...bloques,
  `## Ejecuciones recientes (las ${ejec.length} últimas guardadas; el Monitor de conexión no guarda las correctas)`, ...lineasEjec,
  `## Últimos errores`, ...(errores.length ? errores : ['- ninguno']),
  `## Tablas de datos`, ...bloquesTablas,
].join('\n');
return [{ json: { ...$('Mensaje').first().json, contexto } }];

// Guarda la conversación (últimos 12 mensajes) y parte la respuesta si pasa del límite de Telegram.
const base = $('Mensaje').first().json;
let texto = base.comando === 'nuevo' ? 'Listo, empezamos de cero. ¿Qué quieres saber?' : String($json.text || '').trim();
if (!texto) texto = 'No pude contestar ahora: la IA gratuita no respondió. Prueba otra vez en un rato.';
texto = texto.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^#+\s*/gm, '');
if (base.comando !== 'nuevo') {
  const memoria = $getWorkflowStaticData('global');
  memoria.chats ||= {};
  memoria.chats[base.chat] = [...(memoria.chats[base.chat] || []), { r: 'user', t: base.texto.slice(0, 800) }, { r: 'bot', t: texto.slice(0, 1500) }].slice(-12);
}
const trozos = [];
for (let i = 0; i < texto.length; i += 3900) trozos.push(texto.slice(i, i + 3900));
return trozos.map(t => ({ json: { chat: base.chat, texto: t } }));
